import {SiegeGame,W,H,PLAYER_Y} from './engine.js';
import {readWords} from './vocab.js';
export const SAMPLE=`reduce,減らす\naffect,影響を与える\npublish,出版する\ncompete,競う\nexplore,探索する\nrecognize,認識する\nemphasize,強調する\naccompany,同行する\ncrowded,混雑した\nvaluable,貴重な\naccurate,正確な\ngrant,補助金\ndestination,目的地\ncapacity,能力\nproof,証拠\nanniversary,記念日\nfound,設立する\ninclude,含む`;
const $=id=>document.getElementById(id),canvas=$('gameCanvas'),ctx=canvas.getContext('2d'),stage=$('stage');
const art=new Image();art.src='assets/golem.webp';const cannon=new Image();cannon.src='assets/cannon.webp';
const KEY='vocab-castle-words-v1';let game=null,paused=false,last=0,toastUntil=0,previousGate=null,pointer=null,muted=true,audio=null,lastKillSound=0;
function sound(freq,duration=.08,type='sine',volume=.035){if(muted)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(freq*.55,audio.currentTime+duration);g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}catch{}}
function showToast(text,bad=false){$('toast').textContent=text;$('toast').classList.toggle('bad',bad);$('toast').classList.add('show');toastUntil=performance.now()+2300;}
function event(type,data){
 if(type==='correct'){showToast(`正解！ ${data.word}\n${data.before}連射 → ${data.power}連射`);sound(880,.22,'triangle',.08);}
 if(type==='wrong'){showToast(`${data.unanswered?'門を選べなかった':'不正解'}：${data.word} = ${data.meaning}\n弾数半減・射撃停止`,true);sound(150,.3,'sawtooth',.035);}
 if(type==='damage')sound(110,.15,'triangle',.05);
 if(type==='kill'&&performance.now()-lastKillSound>100){sound(data.type==='brute'?95:320,.05,'triangle',.02);lastKillSound=performance.now();}
 if(type==='boss')showToast('魔王ゴーレム出現\n赤い予告線から移動して避けろ');
 if(type==='bossRage')showToast('魔王が増援を召喚！');
 if(type==='end')queueMicrotask(()=>showEnd(data));
}
function start(raw){const parsed=readWords(raw);if(parsed.errors.length){$('formError').textContent=parsed.errors[0];return false;}try{localStorage.setItem(KEY,raw);}catch{}$('formError').textContent='';$('setupOverlay').classList.add('hidden');$('endOverlay').classList.add('hidden');$('pauseOverlay').classList.add('hidden');paused=false;previousGate=null;game=new SiegeGame(parsed.entries,{onEvent:event});$('aimHint').classList.remove('hidden');sound(500,.12);return true;}
function showEnd(data){if(!game)return;$('endKicker').textContent=data.win?'VICTORY':'DEFEAT';$('endTitle').textContent=data.win?'砦を守りきった！':'砦が陥落した';$('endReason').textContent=data.reason;$('endScore').textContent=game.score.toLocaleString()+' PTS';$('endStats').textContent=`単語 ${game.correct} / ${game.answered} 問正解 · 撃破 ${game.kills} 体`;$('combatStats').textContent=`命中 ${game.stats.hits} 発 / 発射 ${game.stats.fired} 発 · 突破された敵 ${game.stats.breaches} 体`;$('missedList').replaceChildren();for(const e of game.missed.values()){const n=document.createElement('span');n.textContent=e.word+' — '+e.meaning;$('missedList').append(n);}$('missedWrap').classList.toggle('hidden',!game.missed.size);$('endOverlay').classList.remove('hidden');$('gates').classList.add('hidden');$('questionPanel').classList.add('hidden');$('aimHint').classList.add('hidden');}
function setup(){paused=true;game=null;$('setupOverlay').classList.remove('hidden');$('endOverlay').classList.add('hidden');$('pauseOverlay').classList.add('hidden');$('gates').classList.add('hidden');$('questionPanel').classList.add('hidden');}
function setPaused(value){if(!game||game.mode!=='play')return;paused=value;$('pauseOverlay').classList.toggle('hidden',!paused);pointer=null;}
function resize(){const b=stage.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(b.width*d);canvas.height=Math.round(b.height*d);}
function hud(){if(!game)return;const g=game.gate;
 $('waveLabel').textContent=game.bossStarted?'BOSS BATTLE':`GATE ${Math.min(game.gateIndex+1,8)} / 8`;$('ammoLabel').textContent=game.jam>0?'射撃停止':`${game.power} 連射`;$('scoreLabel').textContent=game.score.toLocaleString()+' PTS';$('healthLabel').textContent=game.hp;$('healthFill').style.width=game.hp+'%';$('healthFill').style.background=game.hp<30?'#ff687d':'';
 $('bossHealth').classList.toggle('hidden',!game.bossStarted||game.mode!=='play');if(game.boss)$('bossHealthBar').style.width=Math.max(0,game.boss.hp/game.boss.maxHp*100)+'%';
 const active=!!g&&game.mode==='play';$('questionPanel').classList.toggle('hidden',!active);$('gates').classList.toggle('hidden',!active);
 if(active){if(previousGate!==g){$('questionText').textContent='「'+g.target.meaning+'」';$('questionNumber').textContent=`第${game.gateIndex+1}の門 · 意味に合う単語は？`;const gain=game.power>=24?'最大火力を維持・砦＋5':`弾数 ${g.operation.join('')}（最大24）`;$('rewardText').textContent=`正解：${gain} ／ 不正解：半減・射撃停止`;['gateLeft','gateRight'].forEach((id,i)=>{$(id).querySelector('strong').textContent=g.words[i].word;$(id).setAttribute('aria-label',`${i===0?'左':'右'}の門 ${g.words[i].word}`);});previousGate=g;}
 $('gates').style.top=(g.y/H*100)+'%';$('gateTime').textContent=Math.max(0,g.duration-g.age).toFixed(1)+'秒';$('timerFill').style.transform=`scaleX(${Math.max(0,1-g.age/g.duration)})`;['gateLeft','gateRight'].forEach((id,i)=>$(id).classList.toggle('selected',g.intent&&(i===0?game.player.x<182:game.player.x>218)));}
 $('comboLabel').textContent=game.combo>=5?game.combo+' COMBO':'';$('aimHint').classList.toggle('hidden',game.time>12||game.mode!=='play');$('straightButton').classList.toggle('hidden',!game.aim||game.mode!=='play');
}
function enemy(e){const r=e.r,x=e.x,y=e.y,bob=Math.sin(e.t*8+e.phase)*1.6;
 ctx.save();ctx.translate(x,y+bob);ctx.fillStyle='#08061670';ctx.beginPath();ctx.ellipse(0,r*.8,r*.84,r*.26,0,0,Math.PI*2);ctx.fill();
 if(e.hit>0)ctx.filter='brightness(2.8)';else if(e.type==='runner')ctx.filter='hue-rotate(105deg) saturate(1.4)';else if(e.type==='brute')ctx.filter='hue-rotate(300deg)';else if(e.type==='splitter'||e.type==='shard')ctx.filter='hue-rotate(205deg) saturate(1.4)';else if(e.type==='boss')ctx.filter='hue-rotate(45deg) saturate(1.5)';
 if(art.complete&&art.naturalWidth)ctx.drawImage(art,-r*1.25,-r*1.25,r*2.5,r*2.35);ctx.filter='none';
 if(e.type==='brute'){ctx.strokeStyle='#7ae1fcaa';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,r*.94,0,Math.PI*2);ctx.stroke();}
 if(e.type==='splitter'){ctx.fillStyle=e.color;ctx.font='bold 13px system-ui';ctx.textAlign='center';ctx.fillText('×2',0,-r-8);}
 if(e.maxHp>2&&e.type!=='boss'){ctx.fillStyle='#110c25';ctx.fillRect(-r,-r-5,r*2,4);ctx.fillStyle=e.color;ctx.fillRect(-r,-r-5,r*2*Math.max(0,e.hp/e.maxHp),4);}ctx.restore();
}
function draw(){ctx.setTransform(canvas.width/W,0,0,canvas.height/H,0,0);ctx.clearRect(0,0,W,H);if(!game)return;ctx.save();if(game.shake>0)ctx.translate((Math.random()-.5)*game.shake*12,(Math.random()-.5)*game.shake*12);
 ctx.setLineDash([10,8]);ctx.strokeStyle='#ff868177';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(20,PLAYER_Y-25);ctx.lineTo(380,PLAYER_Y-25);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#efb9bb';ctx.font='9px system-ui';ctx.textAlign='left';ctx.fillText('DEFENSE LINE',20,PLAYER_Y-31);
 if(game.warning){ctx.fillStyle='#ff3c5033';ctx.fillRect(game.warning.x-24,170,48,520);ctx.strokeStyle='#ff677a';ctx.lineWidth=2;ctx.strokeRect(game.warning.x-24,170,48,520);}
 for(const e of [...game.enemies].sort((a,b)=>a.y-b.y))enemy(e);
 ctx.lineCap='round';for(const b of game.shots){ctx.strokeStyle='#b87dff';ctx.lineWidth=6;ctx.globalAlpha=.4;ctx.beginPath();ctx.moveTo(b.x-b.vx*.025,b.y-b.vy*.025);ctx.lineTo(b.x,b.y);ctx.stroke();ctx.globalAlpha=1;ctx.strokeStyle='#ffe3b8';ctx.lineWidth=2.3;ctx.beginPath();ctx.moveTo(b.x-b.vx*.012,b.y-b.vy*.012);ctx.lineTo(b.x,b.y);ctx.stroke();}
 for(const b of game.orbs){ctx.fillStyle='#ffb164';ctx.shadowBlur=12;ctx.shadowColor='#ff3647';ctx.beginPath();ctx.arc(b.x,b.y,b.r,0,Math.PI*2);ctx.fill();}ctx.shadowBlur=0;
 for(const p of game.particles){ctx.save();ctx.globalAlpha=Math.min(1,p.life*2);ctx.translate(p.x,p.y);ctx.rotate(p.angle);ctx.fillStyle=p.color;if(p.kind==='chip'){ctx.fillRect(-p.size/2,-p.size/2,p.size,p.size);}else if(p.kind==='streak'){ctx.fillRect(-p.size/2,-1,p.size*2,2);}else{ctx.beginPath();ctx.arc(0,0,p.size*.5,0,Math.PI*2);ctx.fill();}ctx.restore();}
 for(const r of game.rings){ctx.globalAlpha=r.life;ctx.strokeStyle=r.color;ctx.lineWidth=4;ctx.beginPath();ctx.arc(r.x,r.y,r.r,0,Math.PI*2);ctx.stroke();}ctx.globalAlpha=1;
 if(game.aim){const a=game.aim;ctx.strokeStyle='#faf0c1aa';ctx.lineWidth=1.2;ctx.setLineDash([4,8]);ctx.beginPath();ctx.moveTo(game.player.x,PLAYER_Y-35);ctx.lineTo(a.x,a.y);ctx.stroke();ctx.setLineDash([]);ctx.beginPath();ctx.arc(a.x,a.y,16,0,Math.PI*2);ctx.moveTo(a.x-24,a.y);ctx.lineTo(a.x+24,a.y);ctx.moveTo(a.x,a.y-24);ctx.lineTo(a.x,a.y+24);ctx.stroke();}
 const p=game.player;const satellites=Math.min(4,Math.floor((game.power-1)/4));for(let i=0;i<satellites;i++){const x=p.x+(i%2?1:-1)*(32+Math.floor(i/2)*17);ctx.save();ctx.translate(x,PLAYER_Y+7);ctx.rotate(p.angle);if(cannon.complete&&cannon.naturalWidth)ctx.drawImage(cannon,-16,-27,32,36);ctx.restore();}
 ctx.save();ctx.translate(p.x,PLAYER_Y);ctx.rotate(p.angle);if(game.jam>0)ctx.filter='grayscale(1)';if(cannon.complete&&cannon.naturalWidth)ctx.drawImage(cannon,-32,-49+(game.fireClock<.06?3:0),64,70);ctx.filter='none';if(game.fireClock<.045&&game.jam<=0){ctx.shadowBlur=18;ctx.shadowColor='#d896ff';ctx.fillStyle='#fff4c9';ctx.beginPath();ctx.arc(0,-42,7+game.power*.2,0,Math.PI*2);ctx.fill();}ctx.restore();
 ctx.fillStyle=game.jam>0?'#ff9faa':'#fff0c2';ctx.font='900 16px system-ui';ctx.textAlign='center';ctx.fillText(game.jam>0?'JAMMED':`×${game.power}`,p.x,PLAYER_Y+38);
 if(game.flash>0){ctx.fillStyle=`rgba(255,30,60,${game.flash*.35})`;ctx.fillRect(0,0,W,H);}ctx.restore();
}
function frame(t){const dt=last?Math.min(.04,(t-last)/1000):0;last=t;if(game&&!paused&&!document.hidden)game.update(dt);draw();hud();if(performance.now()>toastUntil)$('toast').classList.remove('show');requestAnimationFrame(frame);}
function coordinates(ev){const b=stage.getBoundingClientRect();return {x:(ev.clientX-b.left)/b.width*W,y:(ev.clientY-b.top)/b.height*H};}
stage.addEventListener('pointerdown',ev=>{if(!game||paused||game.mode!=='play'||ev.target.closest('button,.overlay'))return;const p=coordinates(ev);pointer={id:ev.pointerId,mode:p.y>=H*.82?'move':'aim'};stage.setPointerCapture(ev.pointerId);if(pointer.mode==='move')game.moveTo(p.x);else game.aimTo(p.x,p.y);});
stage.addEventListener('pointermove',ev=>{if(!pointer||pointer.id!==ev.pointerId||paused)return;const p=coordinates(ev);if(pointer.mode==='move')game.moveTo(p.x);else game.aimTo(p.x,p.y);});
stage.addEventListener('pointerup',()=>pointer=null);stage.addEventListener('pointercancel',()=>pointer=null);
$('gateLeft').addEventListener('click',()=>{if(game&&!paused)game.chooseLane(0);});$('gateRight').addEventListener('click',()=>{if(game&&!paused)game.chooseLane(1);});
$('startButton').addEventListener('click',()=>start($('wordsInput').value));$('sampleButton').addEventListener('click',()=>{$('wordsInput').value=SAMPLE;start(SAMPLE);});$('replayButton').addEventListener('click',()=>start($('wordsInput').value));$('changeButton').addEventListener('click',setup);$('editButton').addEventListener('click',setup);$('pauseButton').addEventListener('click',()=>setPaused(true));$('resumeButton').addEventListener('click',()=>setPaused(false));$('straightButton').addEventListener('click',()=>{if(game)game.aim=null;});$('soundButton').addEventListener('click',()=>{muted=!muted;$('soundButton').textContent=muted?'音 OFF':'音 ON';sound(600);});
window.addEventListener('keydown',ev=>{if(!game||game.mode!=='play')return;if(ev.key==='Escape'){setPaused(!paused);return;}if(paused)return;if(ev.key==='ArrowLeft'||ev.key==='a'){ev.preventDefault();game.moveTo(game.player.targetX-42);}if(ev.key==='ArrowRight'||ev.key==='d'){ev.preventDefault();game.moveTo(game.player.targetX+42);}});
document.addEventListener('visibilitychange',()=>{if(document.hidden)setPaused(true);});window.addEventListener('resize',resize);try{$('wordsInput').value=localStorage.getItem(KEY)||'';}catch{}
if(document.modelContext?.registerTool){for(const tool of [{name:'start_vocabulary_game',title:'単語を設定して出撃',description:'単語と訳の行リストを設定して新しいゲームを始める。',inputSchema:{type:'object',properties:{wordList:{type:'string'}},required:['wordList'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(typeof input?.wordList!=='string')throw Error('wordList が必要です');const p=readWords(input.wordList);if(p.errors.length)throw Error(p.errors[0]);$('wordsInput').value=input.wordList;start(input.wordList);return {started:true,wordCount:p.entries.length};}},{name:'move_to_vocabulary_gate',title:'単語の門へ移動',description:'左右の門へ砲台を移動する。門の通過時に解答が確定する。',inputSchema:{type:'object',properties:{side:{type:'string',enum:['left','right']}},required:['side'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!['left','right'].includes(input?.side))throw Error('left または right を指定してください');if(!game?.gate||paused||game.mode!=='play')throw Error('現在は門へ移動できません');game.chooseLane(input.side==='left'?0:1);return {movingTo:input.side,answerConfirmed:false};}}]){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{});}catch{}}}
resize();requestAnimationFrame(frame);
